:where([data-moru-registry]) .ui-pagination {
  box-sizing: border-box;
  min-width: 0;
  max-width: 100%;
  font-family: var(--ui-font-family, inherit);
  font-size: var(--ui-type-body-size, 14px);
  font-weight: var(--ui-type-body-weight, 400);
  line-height: var(--ui-type-body-line-height, 1.6);
  letter-spacing: var(--ui-type-body-letter-spacing, 0em);
  color: var(--ui-text, #171717);
}

:where([data-moru-registry]) .ui-pagination {
  width: 100%;
}
:where([data-moru-registry]) .ui-pagination-list {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  align-items: center;
  gap: calc(var(--ui-space, 4px) / 2);
  margin: 0;
  padding: 0;
  list-style: none;
}
:where([data-moru-registry]) .ui-pagination-button {
  display: inline-flex;
  box-sizing: border-box;
  align-items: center;
  justify-content: center;
  min-width: 36px;
  min-height: max(36px, var(--ui-control-height-sm, 32px));
  padding: var(--ui-space, 4px) calc(var(--ui-space, 4px) * 2);
  border: var(--ui-border-width, 1px) solid transparent;
  border-radius: max(3px, calc(var(--ui-radius, 6px) - 2px));
  background: transparent;
  color: inherit;
  font-family: inherit;
  font-size: var(--ui-type-label-size, 14px);
  font-weight: var(--ui-type-label-weight, 550);
  line-height: var(--ui-type-label-line-height, 1.45);
  cursor: pointer;
}
:where([data-moru-registry]) .ui-pagination-button[aria-current='page'] {
  background: var(--ui-primary, #181818);
  border-color: transparent;
  color: var(--ui-primary-foreground, #fff);
}
:where([data-moru-registry]) .ui-pagination-button:hover:not(:disabled) {
  background: var(--ui-control-hover-bg, #f3f3f1);
}
:where([data-moru-registry]) .ui-pagination-button:active:not(:disabled) {
  background: var(--ui-control-pressed-bg, #e8e8e4);
}
:where([data-moru-registry]) .ui-pagination-button[aria-current='page']:hover:not(:disabled) {
  background: var(--ui-primary-hover, #303030);
  color: var(--ui-primary-hover-foreground, #fff);
}
:where([data-moru-registry]) .ui-pagination-button[aria-current='page']:active:not(:disabled) {
  background: var(--ui-primary-pressed, #0b0b0b);
  color: var(--ui-primary-pressed-foreground, #fff);
}
:where([data-moru-registry]) .ui-pagination-button:disabled {
  color: var(--ui-disabled-text, #a1a1aa);
  cursor: not-allowed;
}
:where([data-moru-registry]) .ui-pagination-ellipsis {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  min-height: 36px;
  color: var(--ui-muted, #6e6e6b);
}

@media (pointer: coarse) {
  :where([data-moru-registry]) .ui-pagination-button {
    min-width: 44px;
    min-height: 44px;
  }
}

:where([data-moru-registry]) .ui-pagination-button:focus-visible {
  outline: 2px solid var(--ui-focus-ring, #181818);
  outline-offset: 2px;
}

'use client'
// Generated from Moru UI source. Do not edit. SPDX-License-Identifier: MIT
import { useI18n } from './_lib/i18n'
import { cn } from './_lib/cn'
import { clampPage, getPaginationItems, normalizePageCount } from './pagination-utils'
import './advanced-controls-shared.css'
import './pagination.css'

export interface PaginationProps {
  page: number
  pageCount: number
  onPageChange: (page: number) => void
  siblingCount?: number
  disabled?: boolean
  'aria-label'?: string
  className?: string
}

export function Pagination({
  page,
  pageCount,
  onPageChange,
  siblingCount = 1,
  disabled,
  'aria-label': ariaLabelProp,
  className,
}: PaginationProps) {
  const { t } = useI18n()
  const ariaLabel = ariaLabelProp ?? t('페이지 탐색')

  const count = normalizePageCount(pageCount)
  const current = clampPage(page, count)
  const changePage = (next: number) => {
    if (!disabled && count > 0 && next !== current) onPageChange(clampPage(next, count))
  }
  return (
    <nav className={cn('ui-pagination', className)} aria-label={ariaLabel}>
      <ul className="ui-pagination-list">
        <li>
          <button
            type="button"
            className="ui-pagination-button"
            aria-label={t('이전 페이지')}
            disabled={disabled || current <= 1}
            onClick={() => changePage(current - 1)}
          >
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
              <path
                d="m10 4-4 4 4 4"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        </li>
        {getPaginationItems(current, count, siblingCount).map((item) => (
          <li key={item}>
            {typeof item === 'number' ? (
              <button
                type="button"
                className="ui-pagination-button"
                aria-label={t('{v0}페이지', { v0: item })}
                aria-current={item === current ? 'page' : undefined}
                disabled={disabled}
                onClick={() => changePage(item)}
              >
                {item}
              </button>
            ) : (
              <span className="ui-pagination-ellipsis" aria-hidden="true">
                …
              </span>
            )}
          </li>
        ))}
        <li>
          <button
            type="button"
            className="ui-pagination-button"
            aria-label={t('다음 페이지')}
            disabled={disabled || count === 0 || current >= count}
            onClick={() => changePage(current + 1)}
          >
            <svg width="16" height="16" viewBox="0 0 16 16" fill="none" aria-hidden="true">
              <path
                d="m6 4 4 4-4 4"
                stroke="currentColor"
                strokeWidth="1.5"
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
          </button>
        </li>
      </ul>
      <span className="ui-advanced-sr-only" role="status" aria-live="polite" aria-atomic="true">
        {count === 0
          ? t('페이지가 없습니다.')
          : t('전체 {v0}페이지 중 {v1}페이지', { v0: count, v1: current })}
      </span>
    </nav>
  )
}
